#include "ksMonoArpTask.h"
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <vector>
using T=ks::MonoArpTask;using S=T::Stage;using C=T::Child;using K=T::Kind;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}int main(){try{uint64_t cases=0;auto verify=[&](unsigned kind,unsigned byte,unsigned count,uint32_t phase,uint32_t deadline,unsigned mode,unsigned enabled){constexpr uint32_t record=0xfffff001,base=0xfffffffe,pattern=0xfffffa00,specialRecord=0x81234567;T t{K(kind),record,base,uint8_t(byte)};std::vector<C>children;unsigned sent=0,publishes=0;uint32_t cursor=0,writtenPhase=0,initialized=0;bool due=deadline>=0xc0000000u&&phase<0x80000000u?true:phase>=0xc0000000u&&deadline<0x80000000u?false:phase>=deadline;while(!t.complete()&&!t.handoff()){if(t.awaitingChild()){auto c=t.child();children.push_back(c);if(c==C::BindPart)check(t.resumePart(record),"Mono partreply");else if(c==C::Event){check(t.timeRecord()==record,"Mono bound eventrecord");check(t.resumeEvent(t.stream()+5,specialRecord),"Mono eventreply");}else if(c==C::Delay){check(t.timeRecord()==(kind==2?specialRecord:record),"Mono delay must use returned event time-record");check(t.resumeDelay(t.stream()+3),"Mono delayreply");}else{if(c==C::Send)++sent;if(c==C::OutputMask)check(t.mask()==uint8_t((1u<<(uint8_t(byte-mode)&7))&enabled),"Mono selected-mode enabledmask");check(t.resumeChild(),"Mono voidreply");}continue;}auto read=[&](S s)->uint32_t{switch(s){case S::InitReadPattern:return byte;case S::InitReadStream:check(t.patternIndex()==uint8_t(byte*4),"Mono bytewrapped patternindex");return pattern;case S::ResetReadPhase:case S::ServiceReadPhase:return phase;case S::ServiceReadDeadline:return deadline;case S::ResetReadStream:case S::MetaReadStream:return pattern;case S::ServiceReadStream:return base;case S::EventRead:case S::MetaRead:return byte;case S::EventReadStatusCount:case S::EventReadDataCount:return count;case S::MetaReadSkip:return count;case S::OutputReadSelected:return byte;case S::OutputReadMode:return mode;case S::OutputReadEnabled:return enabled;default:return uint8_t(t.stream()-base);}};auto write=[&](S s,uint32_t v){++publishes;check(t.timeRecord()==record,"Mono cursorpublication must restore originalrecord");if(s==S::InitPublishStream)initialized=v;else if(s==S::ResetPublishDeadline)writtenPhase=v;else cursor=v;};auto stage=t.stage();auto cost=t.nextClocks(6);check(cost&&t.advanceBefore(cost-1,read,write,[](S){return 6u;})==0&&stage==t.stage(),"Early mono deadline");check(t.advanceBefore(cost,read,write,[](S){return 6u;})==cost,"Mono deadline");}
if(kind==0||kind==1){check(children==std::vector<C>{C::Delay,C::Output},"Mono reset children");check(cursor==pattern+3&&writtenPhase==phase&&t.stream()==base&&t.timeRecord()==record,"Mono reset preserve/publishcursor");check(publishes==unsigned(kind==0?3:2)&&(kind==1||initialized==pattern),"Mono patternpublication");}else if(kind==2){check(children==(due?std::vector<C>{C::BindPart,C::Event,C::Delay}:std::vector<C>{C::BindPart}),"Mono wrap threshold decisions");check(t.timeRecord()==record&&t.stream()==base+(due?8:0)&&publishes==unsigned(due),"Mono service context/returnedcursor");if(due)check(cursor==base+8,"Mono service cursor");}else if(kind==3){if(byte==240||byte==247)check(t.handoff()&&t.route()==(byte==240?T::Route::ExternalStart:T::Route::ExternalContinue),"Mono external SysEx tail");else if(byte==255)check(sent==0&&t.stream()==base+3+count,"Mono inline meta fallback");else check(sent==(byte>=128?count+1:(count?count:256))&&t.stream()==base+(byte>=128?count+1:(count?count:256)),"Mono internal status/data zero256");}else if(kind==4)check(children==std::vector<C>{C::Decode}&&t.timeRecord()==record&&t.stream()==base,"Mono internal wrapper retains context");else if(kind==5){if(byte==47)check(children==std::vector<C>{C::Output}&&t.stream()==pattern,"Mono meta end restarts stream");else check(children.empty()&&t.stream()==base+2+count,"Mono meta byte-skip");}else check(children==std::vector<C>{C::OutputMask}&&t.stream()==base&&t.timeRecord()==record,"Mono output retains context");++cases;};
for(unsigned byte=0;byte<256;++byte)for(unsigned count=0;count<256;++count){verify(3,byte,count,0,0,0,0);verify(5,byte,count,0,0,0,0);verify(6,byte,count,0,0,count,uint8_t(byte+count));verify(4,byte,count,0,0,0,0);}
for(unsigned highPhase=0;highPhase<256;++highPhase)for(unsigned highDeadline=0;highDeadline<256;++highDeadline)for(unsigned low:{0u,0x00ffffffu})verify(2,0,0,(highPhase<<24)|low,(highDeadline<<24)|(0xffffffu-low),0,0);
for(unsigned kind:{0u,1u})for(unsigned pattern=0;pattern<256;++pattern)for(unsigned raw:{0u,1u,127u,255u})verify(kind,pattern,0,raw*0x1010101u,0,raw,pattern);
std::cout<<"PASS: "<<cases<<" pure mono-arp init/service/event/output tasks, independent wrap-time/pattern-alias/context/reply/count/mask/meta oracles, arbitrary returned time-record propagation and early deadlines\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
